    final MainActivity a;final ArrayList<Clip> clips=new ArrayList<>();final ArrayDeque<String> undo=new ArrayDeque<>();
    LinearLayout panel,list;TimelineView view;TextView summary;
    double zoom=1,viewStart;int relink=-1;volatile long rendering=-1;File rendered;MediaPlayer preview;String renderedSignature="";int generation;SeekBar audition;
