    File directory(){File directory=new File(a.getFilesDir(),"amp-lab-timeline");if(!directory.isDirectory()&&!directory.mkdirs())throw new IllegalStateException("Cannot create timeline storage");return directory;}
    static boolean basename(String name){return !name.isEmpty()&&!name.contains("/")&&!name.contains("\\")&&!name.equals(".")&&!name.equals("..");}
    String snapshot()throws Exception{JSONArray values=new JSONArray();for(Clip clip:clips)values.put(clip.json());return values.toString();}
